CWeaponObject::CWeaponObject( IAttributes* attributes ) : CGameObject(attributes)
{
	m_scale = 1.0f;
	m_baseScale = 1.0f;
}

CWeaponObject::~CWeaponObject()
{
}

void CWeaponObject::setLevel(int level)
{
	m_level = level;

	IAttributes * attr;

	if (getType() == WT_Gate && level == WL_None)
	{
		attr = CGameConfig::GetInstance()->getAttributes("gate", "Gate01");
	}
	else
	{
		if (level == WL_None && getType() != WT_Spell)
			level = WL_1;

		attr = GetWeaponInfo(getType(), level).getAttributes();
	}

	setBaseScale( GetFloatWithDefault(attr, "Scale", 1.0f) );

	adjustStats(attr);
}

int CWeaponObject::getLevel()
{
	return m_level;
}

void CWeaponObject::setScale(f32 scale)
{
	m_scale = scale;
	getSceneNode()->setScale(v3f(1,1,1) * m_scale * m_baseScale);
}

void CWeaponObject::setBaseScale(f32 scale)
{
	m_baseScale = scale;
	setScale(m_scale);
}

f32 CWeaponObject::getCooldown()
{
	return 0;
}

void CWeaponObject::reset()
{
	m_readyTime = 1000.0f;
	m_cooldownTime = 0.0f;
}

void CWeaponObject::update(f32 time)
{
	if (getCooldown() == 0.0f)
	{
		m_readyTime += time;
		m_cooldownTime = 0.0f;
	}
	else
	{
		m_readyTime = 0.0f;
		m_cooldownTime += time;
	}
}

void CWeaponObject::drawCooldown(p2i pos)
{
	const float blinkDuration = 1.0f;
	const float fadeDuration = 0.5f;
	const float blinkCount = 4.0f;

	float cooldown = getCooldown();
	if (cooldown == 0.0f && m_readyTime >= blinkDuration + fadeDuration)
		return;

	ASprite* sprite = CPlayfield::GetInstance()->getSpriteIngame();
	r2i clip;
	sprite->GetFrameRect(clip, MENU_F_MENU_COOLDOWN_FILL, 0);
	clip += pos;

	/// Fade
	int alpha;
	if (cooldown == 0.0f)
	{
		alpha = 255 * (1.0f - (m_readyTime - blinkDuration) / fadeDuration);
	}
	else
	{
		alpha = 255 * m_cooldownTime / fadeDuration;
	}
	CLAMP(alpha, 0, 255);
	
	/// Blink
	if (cooldown == 0.0f && m_readyTime < blinkDuration)
	{
		int blink = blinkCount * m_readyTime / blinkDuration;
		if (blink & 1)
		{
			cooldown = 1.0f;
		}
	}

	clip.LowerRightCorner.X = clip.UpperLeftCorner.X + clip.getWidth() * (1.0f - cooldown);

	sprite->PaintFrame(MENU_F_MENU_COOLDOWN_BG, pos.X, pos.Y, alpha);
	ASprite::PushClipRect(clip);
	sprite->PaintFrame(MENU_F_MENU_COOLDOWN_FILL, pos.X, pos.Y, alpha);
	ASprite::PopClipRect();
}

void CWeaponObject::setShopHighlight(f32 power)
{
	SColor emissive = SColor(0xAAAAAAAA).getInterpolated(SColor(0x00000000), power);
	setEmissiveColor(m_Node, emissive);
}
